let marketData=null,marketsBusy=false,focusDeadline=null,focusPaused=1500,focusFinished=false;
const brMoney=(value,decimals=2)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:decimals,maximumFractionDigits:decimals}).format(value);
function marketHistoryPoints(history){if(history.length<2)return'';const values=history.map(p=>p.value),min=Math.min(...values),range=Math.max(...values)-min;return values.map((v,i)=>`${5+i*250/(values.length-1)},${range===0?19:33-(v-min)/range*28}`).join(' ')}
function marketTime(item){const at=item.sourceAt||item.fetchedAt;if(!at)return'Horário indisponível';return (item.sourceAt?'Fonte: ':'Consultado: ')+new Date(at*1000).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'})}
function paintMarkets(){if(!marketData)return;const items=marketData.items;for(const id of ['usd','ibov','usdc']){const item=items[id];const source=$('#'+id+'-source'),price=$('#'+id+'-price'),change=$('#'+id+(id==='usdc'?'-brl':'-change'));change.classList.remove('positive','negative');if(!item?.ok){price.textContent='—';change.textContent='Cotação indisponível';source.textContent=item?.error||'Não foi possível consultar';if(id==='ibov')$('#ibov-line').setAttribute('points','');continue}price.textContent=id==='usd'?brMoney(item.value,4):id==='ibov'?new Intl.NumberFormat('pt-BR',{maximumFractionDigits:0}).format(item.value)+' pts':'US$ '+item.value.toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4});if(id==='usdc')change.textContent=brMoney(item.brl,4)+' por USDC';else{change.textContent=Number.isFinite(item.change)?(item.change>0?'+':'')+item.change.toFixed(2).replace('.',',')+'% · última variação':'Variação não informada';if(Number.isFinite(item.change)&&item.change!==0)change.classList.add(item.change>0?'positive':'negative')}source.textContent=item.source+' · '+marketTime(item);if(id==='ibov'){$('#ibov-line').setAttribute('points',marketHistoryPoints(item.history||[]));$('#ibov-chart').setAttribute('aria-label','Histórico diário recebido do Yahoo Finance; até cinco pregões.')}}const ok=Object.values(items).filter(x=>x.ok).length;$('#market-status').textContent=ok?`${ok} de 3 cotações disponíveis. Câmbio de compra e referências de mercado; podem ter atraso. Clique no card para ver a fonte e o horário.`:'As fontes não responderam. Verifique o serviço local e a internet do Mac. Nenhum valor foi estimado.'}
async function loadMarkets(){if(marketsBusy)return;marketsBusy=true;$('#refresh-markets').disabled=true;try{marketData=await localJSON('/api/markets');paintMarkets()}catch(e){$('#market-status').textContent=e.message;for(const id of ['usd','ibov','usdc'])$('#'+id+'-source').textContent=marketData?'Última consulta salva nesta sessão':'Serviço local necessário'}finally{marketsBusy=false;$('#refresh-markets').disabled=false}}
function marketDetails(id){const item=marketData?.items[id];const names={usd:'Dólar comercial',ibov:'Ibovespa',usdc:'USD Coin'};if(!item?.ok){show(`<p class="eyebrow">PANORAMA</p><h2>${names[id]}</h2><p>A cotação não está disponível. Inicie o serviço local e use Atualizar cotações.</p><button id="retry-market" class="panel-button">Tentar novamente</button>`);$('#retry-market').onclick=async()=>{await loadMarkets();marketDetails(id)};return}show(`<p class="eyebrow">PANORAMA · ${escapeHTML(item.source)}</p><h2>${names[id]}</h2><div class="ambient-detail"><dl><dt>Referência</dt><dd>${escapeHTML(item.label)}</dd><dt>Horário</dt><dd>${escapeHTML(marketTime(item))} · Brasília</dd></dl></div><p>${id==='ibov'?'O índice é apresentado em pontos. A curva usa os valores diários retornados pela fonte, com até cinco pregões. A cotação pode ter atraso; fora do pregão, poderá mostrar o último fechamento.':id==='usd'?'Taxa de compra USD/BRL fornecida pela AwesomeAPI. Não inclui spread, impostos ou tarifas de uma operação.':'Preço de referência de uma unidade de USDC, consultado na Coinbase. O valor em dólar é consultado; não é fixado artificialmente em US$ 1.'}</p><a class="panel-button" href="${escapeHTML(item.url)}" target="_blank" rel="noopener noreferrer">Abrir fonte ↗</a>`)}
for(const id of ['usd','ibov','usdc'])$('#market-'+id).onclick=()=>marketDetails(id);
function conversionValue(amount,from,to,items){if(!Number.isFinite(amount)||amount<0)throw Error('Informe um valor válido, igual ou maior que zero.');if(!['BRL','USD','USDC'].includes(from)||!['BRL','USD','USDC'].includes(to))throw Error('Moeda inválida.');if(from===to)return amount;const rates={BRL:1,USD:items?.usd?.ok?items.usd.value:null,USDC:items?.usdc?.ok?items.usdc.brl:null};if(!Number.isFinite(rates[from])||!Number.isFinite(rates[to])||rates[from]<=0||rates[to]<=0)throw Error('A cotação necessária não está disponível. Atualize o panorama.');return amount*rates[from]/rates[to]}
function converter(){show('<p class="eyebrow">UMA CONTA A MENOS</p><h2>Conversor de moedas</h2><div class="convert-fields"><label>Valor<input id="convert-amount" type="text" inputmode="decimal" value="100" autocomplete="off"></label><label>De<select id="convert-from"><option>USD</option><option>BRL</option><option>USDC</option></select></label><label>Para<select id="convert-to"><option>BRL</option><option>USD</option><option>USDC</option></select></label></div><output id="convert-output" class="convert-result" aria-live="polite">—</output><p id="convert-note" class="inline-note">Referência aproximada, sem impostos ou tarifas.</p>');function calculate(){const raw=$('#convert-amount').value.trim();const amount=/^\d+(?:[.,]\d+)?$/.test(raw)?Number(raw.replace(',','.')):NaN;try{const value=conversionValue(amount,$('#convert-from').value,$('#convert-to').value,marketData?.items);$('#convert-output').textContent=value.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:4})+' '+$('#convert-to').value;$('#convert-note').textContent='Referência aproximada com as últimas cotações do panorama. Fontes com horários distintos; sem impostos ou tarifas.'}catch(e){$('#convert-output').textContent='—';$('#convert-note').textContent=e.message}}for(const id of ['convert-amount','convert-from','convert-to'])$('#'+id).addEventListener('input',calculate);calculate()}
function focusSeconds(){return focusDeadline?Math.max(0,Math.ceil((focusDeadline-Date.now())/1000)):focusPaused}
function focusText(){const s=focusSeconds();return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function focusPanel(){show('<p class="eyebrow">UM MOMENTO DE ATENÇÃO</p><h2>Foco de 25 minutos</h2><div id="focus-clock" class="focus-clock">'+focusText()+'</div><p class="inline-note">O contador funciona enquanto esta página estiver aberta. Ele não silencia a TV nem bloqueia notificações.</p><div class="focus-actions"><button id="focus-toggle" class="panel-button">'+(focusDeadline?'Pausar':'Iniciar')+'</button><button id="focus-reset" class="text-button">Reiniciar</button></div>');$('#focus-toggle').onclick=()=>{if(focusDeadline){focusPaused=focusSeconds();focusDeadline=null}else{if(focusPaused<=0)focusPaused=1500;focusDeadline=Date.now()+focusPaused*1000;focusFinished=false}focusPanel()};$('#focus-reset').onclick=()=>{focusDeadline=null;focusPaused=1500;focusFinished=false;focusPanel()}}
function updateAmbient(){if(weather)$('#ambient-weather-info').textContent=Math.round(weather.current.temperature_2m)+'° · '+weatherDescription(weather.current.weather_code)+(weatherError?' · dados salvos':'');if(focusDeadline||focusPaused!==1500)$('#focus-remaining').textContent=focusText()+(focusDeadline?' · em andamento':' · pausado');else $('#focus-remaining').textContent='Iniciar uma pausa de distrações';if($('#focus-clock'))$('#focus-clock').textContent=focusText();if(focusDeadline&&focusSeconds()===0){focusDeadline=null;focusPaused=0;focusFinished=true;$('#focus-remaining').textContent='Sessão concluída';if($('#focus-toggle'))$('#focus-toggle').textContent='Iniciar';notify('Seu período de foco terminou.')}}
$('#currency-tool').onclick=converter;$('#ambient-weather').onclick=weatherPanel;$('#ambient-system').onclick=systemPanel;$('#focus-tool').onclick=focusPanel;$('#refresh-markets').onclick=loadMarkets;
const previousAmbientNavigate=navigate;navigate=function(next){previousAmbientNavigate(next);if(next==='ambient'){updateAmbient();loadMarkets()}};
setInterval(()=>{if(!document.hidden&&page==='ambient')loadMarkets()},300000);setInterval(()=>{if(!document.hidden&&(page==='ambient'||focusDeadline||$('#focus-clock')))updateAmbient()},1000);
